32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
37	
38	export interface ScenarioResult {
39	  results: StepResult[];
40	}
41	
42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
45	  sword: 100,
46	  staff: 80,
47	  amulet: 60,
48	  potion: 40,
49	  rune: 25,
50	};
51	
52	const FIRST_INSURANCE_PERCENT = 10;
53	
54	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
55	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
56	// is 110.00000000000001 in binary floating point. Since the final amount feeds
57	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
58	const addPercent = (amount: number, percent: number): number =>
59	  amount + (amount * percent) / 100;
60	
61	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
62	
63	const BLOCK_SIZE = 3;
64	const BLOCK_BASE_PREMIUM = 60;
65	
66	const groupBasePremium = (items: Item[]): number => {
67	  if (items.length === BLOCK_SIZE && items[0].type === "rune") {
68	    return BLOCK_BASE_PREMIUM;
69	  }
70	  return items.reduce((sum, item) => sum + itemBasePremium(item), 0);
71	};
72	
73	const quotePremium = (step: QuoteStep): number => {
74	  const policyBasePremium = groupBasePremium(step.items);
75	  return Math.ceil(
76	    addPercent(policyBasePremium, FIRST_INSURANCE_PERCENT) + PROCESSING_FEE,
77	  );
78	};
79	
80	const runStep = (step: Step): StepResult => {
81	  if (step.op === "quote") return { premium: quotePremium(step) };
82	  throw new Error(`Unsupported step: ${step.op}`);
83	};
84	
85	export const runScenario = (scenario: Scenario): ScenarioResult => ({
86	  results: scenario.steps.map(runStep),
87	});
