const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const BLOCK_TYPE = "rune";

const sumItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

const formsBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && items.every((item) => item.type === BLOCK_TYPE);

const policyBasePremium = (items: Item[]): number =>
  formsBlock(items) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(items);

const quotePremium = (step: QuoteStep): number =>
  Math.ceil(
    addPercent(policyBasePremium(step.items), FIRST_INSURANCE_PERCENT) +
      PROCESSING_FEE,
  );
